// The local first pass of "which tools fit this project": words of the person's description against
// each entry's name and description. Free and instant; a small model can refine the result later.

import type { Entry } from '../types'

// Words that say nothing about what is being built, and words every tool name here shares ("claude", "plugin"):
// a name match on one of them would offer a tool for any prompt.
const STOP = new Set([
  'a', 'an', 'the', 'and', 'or', 'to', 'of', 'for', 'in', 'on', 'with', 'my', 'is', 'it', 'i', 'want', 'build', 'make', 'app', 'project',
  'claude', 'code', 'plugin', 'plugins', 'skill', 'skills', 'tool', 'tools', 'helm', 'anthropic', 'use', 'using', 'add', 'fix', 'new', 'file', 'files',
  'this', 'that', 'can', 'you', 'how', 'what', 'are', 'be', 'we', 'not', 'but', 'from', 'at', 'by', 'as', 'so', 'if', 'then', 'do', 'does', 'please',
])

const stems = (text: string): string[] =>
  [...new Set(text.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 1 && !STOP.has(w)))]

/** Every entry that matches `text` at all, with its score and how many different words hit, best first. A hit in the name counts 3, in the description 1. */
export function scored(index: Entry[], text: string): { key: string; score: number; words: number; named: number }[] {
  const want = stems(text)
  if (want.length === 0) return []
  const hit = (found: string[], w: string) => found.some(f => f.startsWith(w) || w.startsWith(f))
  return index
    .map(e => {
      const inName = stems(e.name)
      const inText = stems(e.description)
      return {
        key: e.key,
        score: want.reduce((n, w) => n + (hit(inName, w) ? 3 : 0) + (hit(inText, w) ? 1 : 0), 0),
        words: want.filter(w => hit(inName, w) || hit(inText, w)).length,
        named: want.filter(w => hit(inName, w)).length,
      }
    })
    .filter(r => r.score > 0)
    .sort((a, b) => b.score - a.score || a.key.localeCompare(b.key))
}

/** The keys of the entries that fit `text` best, best first; entries with no match are left out. */
export const shortlist = (index: Entry[], text: string, max = 8): string[] => scored(index, text).slice(0, max).map(r => r.key)

files.src/suggest.ts:
// Two ways to pick tools with more care than a word match, both pure:
//  - a hint while working: a tool that is off and fits the prompt just typed
//  - a refinement: one small-model call that reads the shortlist's candidates and keeps the ones that fit

import type { Entry } from '../types'
import { scored } from './shortlist'

/** A score of 3: one word of the name, or three of the description. */
export const HINT_MIN = 3
/** A tool is only offered when the prompt names it (a word of its name) and a second word fits. A description alone is too wide: long ones match any prompt. */
/** Different words of the prompt that must hit: one word, however strong, is a coincidence. */
export const HINT_WORDS = 2

/** The one off tool that fits a prompt best, or null. Ignored tools never come back. */
export function hintFor(index: Entry[], prompt: string, ignored: string[]): string | null {
  const off = new Map(index.filter(e => !e.on && !ignored.includes(e.key)).map(e => [e.key, e]))
  const best = scored([...off.values()], prompt).find(r => r.words >= HINT_WORDS && r.named >= 1)
  return best && best.score >= HINT_MIN ? best.key : null
}

/** A rough size of a text in tokens, for the price shown before the call. */
export const estimateTokens = (text: string): number => Math.ceil(text.length / 4)

/** The question for the small model: a numbered list of candidates and the person's words. */
export function refinePrompt(candidates: Entry[], text: string): string {
  const list = candidates.map((e, i) => `${i + 1}. ${e.name}: ${e.description || 'no description'}`).join('\n')
  return [
    `A person is working on: "${text}".`,
    'Which of these tools would help? Answer with the numbers of the useful ones as a JSON array, nothing else. Use [] when none help.',
    list,
  ].join('\n')
}

/** The keys the model chose; anything that is not a valid number in range is dropped. */
export function parseChoice(reply: string, candidates: Entry[]): string[] {
  const array = reply.match(/\[[\d,\s]*\]/)
  if (!array) return []
  try {
    const numbers = JSON.parse(array[0]) as unknown[]
    return [...new Set(numbers.filter((n): n is number => Number.isInteger(n) && n >= 1 && n <= candidates.length))].map(n => candidates[n - 1].key)
  } catch {
    return []
  }
}

files.src/project.ts:
// Where a chat runs: the project folder and who it is. Pure.

const slashes = (path: string): string => path.replace(/\\/g, '/').replace(/\/+$/, '')

/** A short, stable id for a folder, the same on every OS and for either slash. */
export function projectKey(root: string): string {
  const text = slashes(root).toLowerCase()
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(36)
}

/** The name a person knows the folder by. */
export const projectName = (root: string): string => slashes(root).split('/').pop() || root

/** The settings file that holds a project's own setup. */
export const localSettings = (root: string): string => `${slashes(root)}/.claude/settings.local.json`

/**
 * Whether a folder can be a project. The home folder and Claude Code's own config folder cannot:
 * their `.claude/settings.json` is the global file, so nothing set there could be "only here".
 */
export function isProject(root: string, configDir: string, home = ''): boolean {
  const r = slashes(root).toLowerCase()
  const c = slashes(configDir).toLowerCase()
  if (r === '' || r === c || `${r}/.claude` === c) return false
  return !(home !== '' && r === slashes(home).toLowerCase())
}

